'use client';

import { cn } from '@/lib/utils';
import {
  type AutocompleteSource,
  type ComposerAutocomplete,
  type TranscriptStopState,
  useComposerAutocomplete,
} from '@dudousxd/nestjs-agent-react';
import { type ChangeEvent, type KeyboardEvent, type ReactNode, useState } from 'react';
import { ChatCommandPalette } from './chat-command-palette';
import { ArrowUpIcon, PaperclipIcon, StopIcon } from './icons';

/** Stable identity so the autocomplete's request effect doesn't re-fire on every render. */
const NO_SOURCES: readonly AutocompleteSource[] = [];

/**
 * Why the menu is empty. A source that offered nothing at all and a query that matched nothing are
 * different facts — "no skills are configured for you" reads as a bug when it says "no matches".
 */
function emptyMenuStatus(autocomplete: ComposerAutocomplete): string {
  if (autocomplete.isLoading) {
    return 'Searching…';
  }
  return autocomplete.query.length > 0 ? 'No matches' : 'Nothing to complete';
}

export interface ChatComposerProps {
  onSubmit: (text: string) => void;
  /**
   * `transcript.stop` from `useChatTranscript`. While it is `available` the submit control becomes
   * the cancel control — one button, because at any moment exactly one of the two is meaningful.
   */
  stop?: TranscriptStopState;
  /** Controlled draft. Omit both to let the composer hold its own. */
  value?: string;
  onValueChange?: (value: string) => void;
  defaultValue?: string;
  placeholder?: string;
  disabled?: boolean;
  onAttach?: () => void;
  attachLabel?: string;
  /** Sits left of the submit control — a model or mode selector, say. */
  trailing?: ReactNode;
  /** Rendered inside the card, below the divider — e.g. `<ChatContextStrip />`. */
  footer?: ReactNode;
  /** Rendered above the card inside the same rounded shell — e.g. a suggestion palette. */
  overlay?: ReactNode;
  /**
   * Triggers the draft completes against — `/` for commands, `@` for a mention. The composer knows
   * nothing about what a source offers; while one is open it takes over ↑ ↓ Enter Tab Esc, and
   * Enter stops sending. Omitted, the composer behaves exactly as it did without them.
   */
  autocompleteSources?: readonly AutocompleteSource[];
  onAutocompleteError?: (error: unknown, source: AutocompleteSource) => void;
  submitLabel?: string;
  /** The key that sends, shown as a hint beside submit. `null` hides the hint. */
  submitHint?: string | null;
  /**
   * What Enter does while a turn is in flight (the button is Stop then). `'submit'` (default) sends —
   * `useAgentChat` queues a message sent mid-turn, so it runs when the turn settles. `'block'`
   * ignores it, for a chat whose backend cannot queue.
   */
  whileBusy?: 'submit' | 'block';
  className?: string;
}

/**
 * The composer as a card: a growing textarea, an attach affordance, a slot for a selector, and one
 * circular control that submits or cancels. Enter sends, Shift+Enter breaks the line.
 */
export function ChatComposer({
  onSubmit,
  stop,
  value,
  onValueChange,
  defaultValue = '',
  placeholder = 'Ask anything',
  disabled = false,
  onAttach,
  attachLabel = 'Attach a file',
  trailing,
  footer,
  overlay,
  autocompleteSources,
  onAutocompleteError,
  submitLabel = 'Send',
  submitHint = 'Enter',
  whileBusy = 'submit',
  className,
}: ChatComposerProps) {
  const [internal, setInternal] = useState(defaultValue);
  const draft = value ?? internal;
  const isBusy = stop?.available === true;

  function setDraft(next: string) {
    if (value === undefined) {
      setInternal(next);
    }
    onValueChange?.(next);
  }

  const autocomplete = useComposerAutocomplete({
    value: draft,
    onValueChange: setDraft,
    sources: autocompleteSources ?? NO_SOURCES,
    ...(onAutocompleteError !== undefined ? { onError: onAutocompleteError } : {}),
  });
  const inputProps = autocomplete.getInputProps();

  function submit() {
    const trimmed = draft.trim();
    if (!trimmed || disabled || (isBusy && whileBusy === 'block')) {
      return;
    }
    onSubmit(trimmed);
    setDraft('');
  }

  function handleKeyDown(event: KeyboardEvent<HTMLTextAreaElement>) {
    // The open menu gets first refusal: it marks the keys it consumed as handled, and Enter picking
    // a command must never also send the half-typed line.
    inputProps.onKeyDown(event);
    if (event.defaultPrevented) {
      return;
    }
    if (event.key === 'Enter' && !event.shiftKey) {
      event.preventDefault();
      submit();
    }
  }

  function handleChange(event: ChangeEvent<HTMLTextAreaElement>) {
    setDraft(event.target.value);
    inputProps.onChange(event);
  }

  return (
    <div
      data-slot="chat-composer"
      className={cn(
        'group/composer rounded-2xl border border-border bg-card text-card-foreground shadow-sm',
        'focus-within:border-ring focus-within:ring-[3px] focus-within:ring-ring/40',
        'transition-[color,box-shadow]',
        className,
      )}
    >
      {autocomplete.isOpen ? (
        <ChatCommandPalette
          suggestions={autocomplete.items.map((item) => ({
            id: item.id,
            label: item.label,
            ...(item.description !== undefined ? { description: item.description } : {}),
            ...(item.hint !== undefined ? { hint: item.hint } : {}),
          }))}
          onSelect={(suggestion) => {
            const picked = autocomplete.items.find((item) => item.id === suggestion.id);
            if (picked) {
              autocomplete.accept(picked);
            }
          }}
          onClose={autocomplete.dismiss}
          activeIndex={autocomplete.activeIndex}
          onActiveIndexChange={autocomplete.highlight}
          listboxProps={autocomplete.getListboxProps()}
          getOptionProps={autocomplete.getOptionProps}
          status={autocomplete.error ?? emptyMenuStatus(autocomplete)}
        />
      ) : (
        overlay
      )}
      <div className="px-3 pt-3">
        <textarea
          {...inputProps}
          rows={2}
          value={draft}
          disabled={disabled}
          placeholder={placeholder}
          aria-label={placeholder}
          onChange={handleChange}
          onKeyDown={handleKeyDown}
          // `field-sizing-content` grows the box with the text and needs no measuring pass; the
          // max height keeps a pasted essay from swallowing the transcript.
          className={cn(
            'field-sizing-content max-h-56 w-full resize-none bg-transparent text-base',
            'text-foreground placeholder:text-muted-foreground outline-none',
            'disabled:cursor-not-allowed disabled:opacity-60',
          )}
        />
      </div>

      <div className="flex items-center gap-2 px-3 pb-3 pt-2">
        {onAttach ? (
          <button
            type="button"
            onClick={onAttach}
            disabled={disabled}
            aria-label={attachLabel}
            title={attachLabel}
            className={cn(
              'flex size-8 items-center justify-center rounded-lg text-muted-foreground',
              'transition-colors outline-none hover:bg-accent hover:text-foreground',
              'focus-visible:ring-[3px] focus-visible:ring-ring/50',
              'disabled:pointer-events-none disabled:opacity-50',
            )}
          >
            <PaperclipIcon className="size-4.5" />
          </button>
        ) : null}

        <div className="ml-auto flex items-center gap-2">
          {trailing}
          {submitHint !== null && !isBusy ? (
            <span className="hidden items-center gap-1.5 text-xs text-muted-foreground group-focus-within/composer:flex">
              {submitLabel}
              <kbd className="rounded border border-border bg-muted px-1.5 py-0.5 font-sans text-[0.6875rem] leading-none">
                {submitHint}
              </kbd>
            </span>
          ) : null}
          {isBusy && stop ? (
            <button
              type="button"
              onClick={stop.stop}
              disabled={stop.isStopping}
              aria-label={stop.isStopping ? 'Stopping' : 'Stop generating'}
              title={stop.isStopping ? 'Stopping…' : 'Stop generating'}
              className={cn(
                'flex size-9 items-center justify-center rounded-full',
                'bg-foreground text-background transition-opacity outline-none',
                'hover:opacity-90 focus-visible:ring-[3px] focus-visible:ring-ring/50',
                'disabled:opacity-60',
              )}
            >
              <StopIcon className="size-4" />
            </button>
          ) : (
            <button
              type="button"
              onClick={submit}
              disabled={disabled || draft.trim().length === 0}
              aria-label={submitLabel}
              title={submitLabel}
              className={cn(
                'flex size-9 items-center justify-center rounded-full',
                'bg-foreground text-background transition-opacity outline-none',
                'hover:opacity-90 focus-visible:ring-[3px] focus-visible:ring-ring/50',
                'disabled:pointer-events-none disabled:opacity-40',
              )}
            >
              <ArrowUpIcon className="size-4.5" />
            </button>
          )}
        </div>
      </div>

      {footer}
    </div>
  );
}

'use client';

import { cn } from '@/lib/utils';
import type { ReactNode } from 'react';
import { PlusIcon } from './icons';

/** One named thing the next turn can read. What it stands for is the host's business. */
export interface ChatContextSource {
  id: string;
  label: string;
  icon?: ReactNode;
}

export interface ChatContextStripProps {
  sources: ChatContextSource[];
  /**
   * How many sources exist in total, when more are connected than are in scope. Omitted means the
   * listed ones are all of them.
   */
  total?: number;
  /** Overrides the "Reading 4 of 9 sources" line; `shown` is `sources.length`. */
  renderSummary?: (shown: number, total: number) => ReactNode;
  onAdd?: () => void;
  addLabel?: string;
  className?: string;
}

/**
 * The composer saying what is in scope BEFORE the question is asked, so the answer's reach is not a
 * surprise. Purely declarative — it lists what it is handed and reports the add press.
 */
export function ChatContextStrip({
  sources,
  total,
  renderSummary,
  onAdd,
  addLabel = 'Add a source',
  className,
}: ChatContextStripProps) {
  const shown = sources.length;
  const all = total ?? shown;

  return (
    <div
      data-slot="chat-context-strip"
      className={cn(
        'flex items-center justify-between gap-3 border-t border-border px-3 py-2',
        className,
      )}
    >
      <p className="min-w-0 truncate text-sm text-muted-foreground">
        {renderSummary
          ? renderSummary(shown, all)
          : `Reading ${shown} of ${all} ${all === 1 ? 'source' : 'sources'}`}
      </p>
      <div className="flex shrink-0 items-center gap-1.5">
        <ul className="flex items-center gap-1.5">
          {sources.map((source) => (
            <li key={source.id}>
              <span
                title={source.label}
                className="flex size-7 items-center justify-center rounded-md text-muted-foreground [&_svg]:size-4"
              >
                {source.icon ?? (
                  <span className="text-xs font-semibold uppercase">
                    {source.label.slice(0, 1)}
                  </span>
                )}
                <span className="sr-only">{source.label}</span>
              </span>
            </li>
          ))}
        </ul>
        {onAdd ? (
          <button
            type="button"
            onClick={onAdd}
            aria-label={addLabel}
            title={addLabel}
            className={cn(
              'flex size-7 items-center justify-center rounded-full border border-border text-muted-foreground',
              'transition-colors outline-none hover:bg-accent hover:text-foreground',
              'focus-visible:ring-[3px] focus-visible:ring-ring/50 focus-visible:border-ring',
            )}
          >
            <PlusIcon className="size-3.5" />
          </button>
        ) : null}
      </div>
    </div>
  );
}

'use client';

import { cn } from '@/lib/utils';
import type { ReactNode } from 'react';

/**
 * A way of running the turn, not a canned prompt: picking one changes which agent, tools or output
 * shape the next message uses, so the pill stays selected after sending rather than filling the box.
 */
export interface ChatMode {
  id: string;
  label: string;
  icon?: ReactNode;
  /** Accessible detail — what choosing this mode changes. */
  description?: string;
  disabled?: boolean;
}

export interface ChatModePillsProps {
  modes: ChatMode[];
  /** The selected mode's id. `null` for "no mode", which is a legitimate state. */
  value?: string | null;
  onSelect?: (mode: ChatMode) => void;
  /** Names the group for screen readers. */
  label?: string;
  className?: string;
}

export function ChatModePills({
  modes,
  value = null,
  onSelect,
  label = 'Response mode',
  className,
}: ChatModePillsProps) {
  return (
    <fieldset
      aria-label={label}
      data-slot="chat-mode-pills"
      className={cn('flex flex-wrap justify-center gap-2', className)}
    >
      {modes.map((mode) => {
        const isSelected = mode.id === value;
        return (
          <button
            key={mode.id}
            type="button"
            aria-pressed={isSelected}
            disabled={mode.disabled === true}
            title={mode.description}
            onClick={() => onSelect?.(mode)}
            className={cn(
              'inline-flex items-center gap-2 rounded-full border px-4 py-2 text-sm font-medium',
              'transition-colors outline-none',
              'focus-visible:ring-[3px] focus-visible:ring-ring/50 focus-visible:border-ring',
              'disabled:pointer-events-none disabled:opacity-50',
              isSelected
                ? 'border-foreground/20 bg-accent text-accent-foreground shadow-xs'
                : 'border-border bg-background text-muted-foreground hover:bg-accent/50 hover:text-foreground',
            )}
          >
            {mode.icon ? <span className="[&_svg]:size-4 shrink-0">{mode.icon}</span> : null}
            {mode.label}
          </button>
        );
      })}
    </fieldset>
  );
}

'use client';

import { cn } from '@/lib/utils';
import type {
  AutocompleteListboxProps,
  AutocompleteOptionProps,
} from '@dudousxd/nestjs-agent-react';
import { type KeyboardEvent, type ReactNode, useState } from 'react';
import { EnterIcon, XIcon } from './icons';

export interface ChatSuggestion {
  id: string;
  label: string;
  /** Second line — what the command does, who the mention is. */
  description?: ReactNode;
  /** Right-aligned aside — where it came from, a shortcut. */
  hint?: ReactNode;
  icon?: ReactNode;
}

export interface ChatCommandPaletteProps {
  suggestions: ChatSuggestion[];
  onSelect: (suggestion: ChatSuggestion) => void;
  onClose?: () => void;
  /**
   * Drive the highlight from elsewhere — the composer's textarea, so ↑/↓ work without leaving the
   * box. Omit both to let the palette own it, in which case the keys work once focus is inside.
   */
  activeIndex?: number;
  onActiveIndexChange?: (index: number) => void;
  /**
   * `autocomplete.getListboxProps()` / `getOptionProps(i)`. Supplying them turns the list into the
   * popup half of a combobox: the rows become `option`s the textarea's `aria-activedescendant`
   * points at, and they stop being focus stops — focus never leaves the composer while the user is
   * still typing the query. Omitted, the list stays a plain set of buttons a host clicks.
   */
  listboxProps?: AutocompleteListboxProps;
  getOptionProps?: (index: number) => AutocompleteOptionProps;
  /** Stands in for the rows: "Searching…", "No matches", what a source that failed said. */
  status?: ReactNode;
  className?: string;
}

/** Suggestions above the composer, with the keys that drive them spelled out. */
export function ChatCommandPalette({
  suggestions,
  onSelect,
  onClose,
  activeIndex,
  onActiveIndexChange,
  listboxProps,
  getOptionProps,
  status,
  className,
}: ChatCommandPaletteProps) {
  const [internalIndex, setInternalIndex] = useState(0);
  const active = activeIndex ?? internalIndex;

  function moveTo(index: number) {
    const wrapped = (index + suggestions.length) % suggestions.length;
    if (activeIndex === undefined) {
      setInternalIndex(wrapped);
    }
    onActiveIndexChange?.(wrapped);
  }

  function handleKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    if (suggestions.length === 0) {
      return;
    }
    if (event.key === 'ArrowDown') {
      event.preventDefault();
      moveTo(active + 1);
      return;
    }
    if (event.key === 'ArrowUp') {
      event.preventDefault();
      moveTo(active - 1);
      return;
    }
    if (event.key === 'Enter') {
      const suggestion = suggestions[active];
      if (suggestion) {
        event.preventDefault();
        onSelect(suggestion);
      }
      return;
    }
    if (event.key === 'Escape') {
      event.preventDefault();
      onClose?.();
    }
  }

  if (suggestions.length === 0 && !status) {
    return null;
  }

  return (
    <div
      onKeyDown={handleKeyDown}
      data-slot="chat-command-palette"
      className={cn('border-b border-border px-2 pt-2 pb-1', className)}
    >
      <div className="flex items-center gap-2 px-1 pb-2 text-xs text-muted-foreground">
        <KeyHint keys={['↑', '↓']} action="navigate" />
        <KeyHint keys={['Enter']} action="select" />
        <span className="ml-auto flex items-center gap-1.5">
          <kbd className="rounded border border-border bg-muted px-1.5 py-0.5 font-sans text-[0.6875rem] leading-none">
            Esc
          </kbd>
          {onClose ? (
            <button
              type="button"
              onClick={onClose}
              aria-label="Dismiss suggestions"
              className={cn(
                'flex size-5 items-center justify-center rounded transition-colors outline-none',
                'hover:bg-accent hover:text-foreground focus-visible:ring-[3px] focus-visible:ring-ring/50',
              )}
            >
              <XIcon className="size-3.5" />
            </button>
          ) : null}
        </span>
      </div>

      {status && suggestions.length === 0 ? (
        <p className="px-2 py-1.5 text-sm text-muted-foreground">{status}</p>
      ) : null}

      <ul aria-label="Suggestions" {...listboxProps} className="flex flex-col">
        {suggestions.map((suggestion, index) => (
          <SuggestionRow
            key={suggestion.id}
            suggestion={suggestion}
            isActive={index === active}
            optionProps={getOptionProps?.(index)}
            onHighlight={() => moveTo(index)}
            onSelect={() => onSelect(suggestion)}
          />
        ))}
      </ul>
    </div>
  );
}

function SuggestionRow({
  suggestion,
  isActive,
  optionProps,
  onHighlight,
  onSelect,
}: {
  suggestion: ChatSuggestion;
  isActive: boolean;
  optionProps: AutocompleteOptionProps | undefined;
  onHighlight: () => void;
  onSelect: () => void;
}) {
  const className = cn(
    'flex w-full items-center gap-2 rounded-lg px-2 py-1.5 text-left text-sm',
    'transition-colors outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50',
    isActive ? 'bg-accent text-accent-foreground' : 'text-muted-foreground hover:bg-accent/50',
  );
  const body = (
    <>
      <span className="shrink-0 [&_svg]:size-3.5">
        {suggestion.icon ?? <EnterIcon className="size-3.5" />}
      </span>
      <span className="min-w-0 truncate">{suggestion.label}</span>
      {suggestion.description ? (
        <span className="min-w-0 flex-1 truncate text-xs text-muted-foreground/80">
          {suggestion.description}
        </span>
      ) : null}
      {suggestion.hint ? (
        <span className="ml-auto shrink-0 truncate text-xs text-muted-foreground/70">
          {suggestion.hint}
        </span>
      ) : null}
    </>
  );

  // Under the combobox wiring the row IS the `option` the textarea points at, so it carries the
  // click itself: a focusable button inside an option would both steal focus from the composer and
  // nest an interactive element where ARIA forbids one.
  if (optionProps) {
    return (
      <li {...optionProps} onMouseEnter={onHighlight} onClick={onSelect} className={className}>
        {body}
      </li>
    );
  }
  return (
    <li>
      <button
        type="button"
        onClick={onSelect}
        onMouseEnter={onHighlight}
        aria-current={isActive}
        className={className}
      >
        {body}
      </button>
    </li>
  );
}

function KeyHint({ keys, action }: { keys: string[]; action: string }) {
  return (
    <span className="flex items-center gap-1">
      {keys.map((key) => (
        <kbd
          key={key}
          className="rounded border border-border bg-muted px-1.5 py-0.5 font-sans text-[0.6875rem] leading-none"
        >
          {key}
        </kbd>
      ))}
      {action}
    </span>
  );
}

import type { SVGProps } from 'react';

/**
 * The glyphs this block needs, inline. Icon libraries disagree on name, size and stroke, so a
 * registry that imported one would drag that choice into every project that installs it; these are
 * `currentColor` strokes on a 24-unit grid, replaceable one at a time.
 */
type IconProps = SVGProps<SVGSVGElement>;

function Icon({ children, ...props }: IconProps) {
  return (
    <svg
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth={1.75}
      strokeLinecap="round"
      strokeLinejoin="round"
      aria-hidden="true"
      focusable="false"
      {...props}
    >
      {children}
    </svg>
  );
}

export function PaperclipIcon(props: IconProps) {
  return (
    <Icon {...props}>
      <path d="M21 11.5 12.5 20a5 5 0 0 1-7-7l8-8a3.5 3.5 0 0 1 5 5l-8 8a2 2 0 0 1-3-3l7.5-7.5" />
    </Icon>
  );
}

export function ArrowUpIcon(props: IconProps) {
  return (
    <Icon {...props}>
      <path d="M12 19V5" />
      <path d="m5 12 7-7 7 7" />
    </Icon>
  );
}

export function ArrowDownIcon(props: IconProps) {
  return (
    <Icon {...props}>
      <path d="M12 5v14" />
      <path d="m19 12-7 7-7-7" />
    </Icon>
  );
}

export function StopIcon(props: IconProps) {
  return (
    <Icon {...props}>
      <rect x="7" y="7" width="10" height="10" rx="1.5" fill="currentColor" stroke="none" />
    </Icon>
  );
}

export function PlusIcon(props: IconProps) {
  return (
    <Icon {...props}>
      <path d="M12 5v14" />
      <path d="M5 12h14" />
    </Icon>
  );
}

export function XIcon(props: IconProps) {
  return (
    <Icon {...props}>
      <path d="m6 6 12 12" />
      <path d="m18 6-12 12" />
    </Icon>
  );
}

export function ChevronDownIcon(props: IconProps) {
  return (
    <Icon {...props}>
      <path d="m6 9 6 6 6-6" />
    </Icon>
  );
}

export function CheckIcon(props: IconProps) {
  return (
    <Icon {...props}>
      <path d="m5 12.5 4.5 4.5L19 7" />
    </Icon>
  );
}

export function CopyIcon(props: IconProps) {
  return (
    <Icon {...props}>
      <rect x="9" y="9" width="11" height="11" rx="2" />
      <path d="M5 15V6a2 2 0 0 1 2-2h9" />
    </Icon>
  );
}

export function PencilIcon(props: IconProps) {
  return (
    <Icon {...props}>
      <path d="M4 20h4L20 8a2.8 2.8 0 0 0-4-4L4 16v4Z" />
    </Icon>
  );
}

export function BranchIcon(props: IconProps) {
  return (
    <Icon {...props}>
      <circle cx="7" cy="5" r="2.2" />
      <circle cx="7" cy="19" r="2.2" />
      <circle cx="17" cy="9" r="2.2" />
      <path d="M7 7.2v9.6" />
      <path d="M17 11.2c0 3-3 3.8-6 4.4" />
    </Icon>
  );
}

export function RefreshIcon(props: IconProps) {
  return (
    <Icon {...props}>
      <path d="M20 11a8 8 0 0 0-13.7-5.2L4 8" />
      <path d="M4 4v4h4" />
      <path d="M4 13a8 8 0 0 0 13.7 5.2L20 16" />
      <path d="M20 20v-4h-4" />
    </Icon>
  );
}

export function DocumentIcon(props: IconProps) {
  return (
    <Icon {...props}>
      <path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8Z" />
      <path d="M14 3v5h5" />
    </Icon>
  );
}

export function WrenchIcon(props: IconProps) {
